// Google Drive's Download node stores the file under a binary property —
// "data" by default. That property's .data field is ALREADY base64-encoded
// in n8n's standard (non-filesystem) binary storage mode — no conversion
// step needed, just read it. If this comes back empty, the binary property
// on your Download node might be named differently; check its Output panel.
const propName = Object.keys($input.item.binary || {})[0] || 'data';
const bin = $input.item.binary[propName];
if (!bin || !bin.data) throw new Error(`No binary data under property "${propName}" — check the Download node's binary property name.`);

return [{ json: {
  base64: bin.data,
  mimeType: bin.mimeType || 'application/pdf',
  fileName: bin.fileName || 'invoice',
  isPdf: (bin.mimeType || '').includes('pdf'),
} }];

// Anthropic's Messages API content-block format for documents vs images —
// same shape whether called from a browser or, as here, from n8n directly.
// Model name is a Settings field, not hardcoded: model strings get retired
// and a template that silently breaks on a stale model name is worse than
// one that asks you to check Anthropic's current model list.
const f = $json;
const cfg = $('Set Configuration Parameters').first().json;

const SYSTEM = `You are an invoice-data extraction system. You will be shown an image or PDF of an invoice. Extract the following fields and respond with ONLY a JSON object — no markdown fences, no other text:

{
  "vendor_name": string or null,
  "invoice_number": string or null,
  "invoice_date": "YYYY-MM-DD" or null,
  "due_date": "YYYY-MM-DD" or null,
  "currency": string (3-letter code) or null,
  "subtotal": number or null,
  "tax": number or null,
  "total": number or null,
  "line_items": [{"description": string, "amount": number}],
  "confidence": "high" | "medium" | "low",
  "extraction_notes": string
}

Rules:
- If a field is not visible, use null. Never guess a plausible-looking number.
- If this does not look like an invoice at all, null every field and say why in extraction_notes.
- Respond with raw JSON only, nothing else.`;

const contentBlock = f.isPdf
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: f.base64 } }
  : { type: 'image', source: { type: 'base64', media_type: f.mimeType || 'image/jpeg', data: f.base64 } };

return [{ json: {
  model: cfg.anthropicModel || 'claude-sonnet-4-6',
  max_tokens: 1500,
  system: SYSTEM,
  messages: [{ role: 'user', content: [contentBlock, { type: 'text', text: 'Extract the invoice fields as JSON.' }] }],
} }];

// Claude is asked for raw JSON but models occasionally wrap it in fences
// anyway — strip those before parsing. A parse failure is treated as a hard
// signal to route this invoice to manual review, not a crash: an
// unreadable extraction is exactly the kind of thing a human should see.
const src = $('Normalize Invoice Data').first().json;
let text = '';
try {
  const blocks = $json.content || [];
  text = blocks.map(b => b.text || '').join('').trim();
} catch (e) { /* fall through with empty text */ }

let data = null, parse_error = null;
try {
  data = JSON.parse(text.replace(/```json|```/gi, '').trim());
} catch (e) {
  parse_error = String(e.message || e);
}

if (!data) {
  return [{ json: {
    ...src, extraction_failed: true, parse_error, raw_response: text.slice(0, 500),
    vendor_name: null, invoice_number: null, total: null, subtotal: null, tax: null,
  } }];
}

return [{ json: { ...src, extraction_failed: false, ...data } }];

// Deterministic arithmetic check — never trust a model's own addition.
// A mismatch here is treated as seriously as a duplicate: something is
// wrong with this invoice and it goes straight to a human, no auto-approve
// path regardless of amount.
const p = $json;
const sub = Number(p.subtotal), tax = Number(p.tax), tot = Number(p.total);
let math_ok = true, math_note = '';

if (p.extraction_failed) {
  math_ok = false; math_note = 'Extraction failed — cannot validate.';
} else if ([sub, tax, tot].some(isNaN)) {
  math_ok = false; math_note = 'One or more amounts missing — cannot validate.';
} else {
  const diff = Math.abs((sub + tax) - tot);
  math_ok = diff < 0.02; // rounding tolerance
  math_note = math_ok ? '' : `subtotal + tax = ${(sub + tax).toFixed(2)}, but total says ${tot.toFixed(2)}`;
}
return [{ json: { ...p, math_ok, math_note } }];

// $input here is the filtered read of the ledger for this invoice_number.
// Any row returned means we have seen this invoice_number before.
const p = $('Perform Arithmetic Check').first().json;
const existing = $input.all();
return [{ json: { ...p, is_duplicate: existing.length > 0,
  duplicate_note: existing.length ? `Invoice #${p.invoice_number} already logged on ${existing[0].json.processed_at || 'an earlier run'}.` : '' } }];

const p = $json;
const resumeUrl = $execution.resumeUrl;
const approve = `${resumeUrl}?decision=APPROVED`;
const reject = `${resumeUrl}?decision=REJECTED`;
const reasons = [];
if (p.extraction_failed) reasons.push('extraction failed');
if (!p.math_ok) reasons.push(`math mismatch (${p.math_note})`);
if (p.is_duplicate) reasons.push(p.duplicate_note);
if (!reasons.length) reasons.push(`amount ${p.total} ${p.currency || ''} is above the auto-approve threshold`);

const lines = [
  `🧾 Invoice needs a human — ${reasons.join('; ')}`,
  p.vendor_name ? `Vendor: ${p.vendor_name}` : '',
  p.invoice_number ? `Invoice #: ${p.invoice_number}` : '',
  (p.total != null) ? `Total: ${p.total} ${p.currency || ''}` : '',
  '',
  `✅ Approve → ${approve}`,
  `❌ Reject → ${reject}`,
];
return [{ json: { ...p, review_text: lines.filter(Boolean).join('\n') } }];

const inv = $('Build Approval Request').first().json;
const decision = ($json.query && $json.query.decision) || ($json.body && $json.body.decision) || 'REJECTED';
return [{ json: { ...inv, approval_type: 'human', final_status: String(decision).toUpperCase() === 'APPROVED' ? 'APPROVED' : 'REJECTED' } }];

// $input is the filtered ledger read (matching vendor, status = APPROVED).
// Gives budget visibility for free — no separate spend-tracking tool needed.
const p = $('Aggregate for Logging').first().json;
const rows = $input.all();
const priorSpend = rows.reduce((sum, r) => sum + (Number(r.json.total) || 0), 0);
return [{ json: { ...p, vendor_prior_spend: priorSpend, vendor_spend_incl_this: priorSpend + (Number(p.total) || 0) } }];

const p = $json;
return [{ json: {
  processed_at: new Date().toISOString().slice(0, 19).replace('T', ' '),
  status: p.final_status || (p.is_duplicate || !p.math_ok || p.extraction_failed ? 'FLAGGED' : 'AUTO_APPROVED'),
  vendor_name: p.vendor_name || '', invoice_number: p.invoice_number || '',
  invoice_date: p.invoice_date || '', due_date: p.due_date || '',
  subtotal: p.subtotal ?? '', tax: p.tax ?? '', total: p.total ?? '', currency: p.currency || '',
  math_ok: String(p.math_ok), duplicate: String(!!p.is_duplicate),
  approval_type: p.approval_type || 'n/a',
  notes: [p.math_note, p.duplicate_note, p.extraction_notes, p.parse_error].filter(Boolean).join(' | '),
  file_id: p.fileId || '', file_name: p.fileName || '',
} }];
